const selected=new Set();let currentRows=[],busy=false,keyBlocked=false,dbBlocked=false,gameBlocked=false,autoRefreshTimer=null,partyDebugTimer=null,marketKindsTimer=null,marketKindsExpected=null,gameMaxUser=0,lastRobotsRefresh=0,dangerousDeleteToken='';const robotsRefreshMs=30000;
function byId(id){return document.getElementById(id)}function text(v){return String(v??'')}function escapeHTML(v){return text(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(msg){const t=byId('toast');t.textContent=i18nMessage(msg);t.style.display='block';clearTimeout(t._timer);t._timer=setTimeout(()=>t.style.display='none',3600)}
function actionName(cmd){return i18nText(({robotsOnlineAsync:'Online',robotsStoreAsync:'Store',robotsLogoutAsync:'Logout',cleanupRobotsAsync:'Cleanup',robotsMove:'Move',robotsShout:'Shout'}[cmd]||cmd))}
function jobGrowName(job,grow){const table=I18N_MESSAGES.zh||{},key='job.'+job+'.'+grow,base='job.'+job+'.0';if(table[key])return table[key];return table[base]?table[base]+' '+text(grow):text(job)+'/'+text(grow)}
function villageDisplay(a){return a.village_name||text(a.village)}
function setBusy(v){busy=v;document.querySelectorAll('button').forEach(b=>b.disabled=v);applyKeyGate()}function applyKeyGate(){const blocked=keyBlocked||dbBlocked||gameBlocked;document.querySelectorAll('[data-key-action="1"]').forEach(b=>b.disabled=busy||blocked);const kb=byId('keyButton');if(kb)kb.disabled=busy;const cb=byId('cleanupButton');if(cb)cb.disabled=busy;applyBackendCapabilities()}
function apiErrorMessage(x,status){if(x&&x.error)return x.error;const result=resultOf(x)||{},robot=(result.robots||[]).find(item=>item&&item.message);if(robot&&robot.message)return robot.message;return 'HTTP '+status}
async function api(command,payload={}){const r=await fetch('/api/call',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({command,payload})});const x=await r.json().catch(()=>({ok:false,error:i18nFormat('error.invalid_json')}));if(!r.ok||!x.ok)throw new Error(apiErrorMessage(x,r.status));return x}
function resultOf(x){return x&&x.result&&x.result.result?x.result.result:x.result}function writeLog(v){try{console.log(v)}catch(e){}}
async function guarded(name,fn){if(busy)return;setBusy(true);try{const out=await fn();if(out!==undefined)writeLog(out);toast(i18nFormat('result.ok',{action:i18nText(name)}))}catch(e){writeLog({ok:false,error:e.message});toast(i18nFormat('result.failed',{action:i18nText(name),error:i18nText(e.message)}))}finally{setBusy(false)}}
async function refreshAll(){await guarded('Refresh',async()=>{await Promise.all([refreshStatus(),refreshScheduler(),refreshRobots(),checkGame(),checkServices(),refreshDatabase(),refreshKeypair()]);return 'refreshed '+new Date().toLocaleTimeString()})}
async function refreshQuiet(){if(busy||document.hidden||byId('autoRefreshInterval')?.value==='off')return;try{const tasks=[refreshStatus(),refreshScheduler(),checkGame(),checkServices(),refreshDatabase(),refreshKeypair()];if(Date.now()-lastRobotsRefresh>=robotsRefreshMs)tasks.push(refreshRobots());await Promise.all(tasks)}catch(e){}}
async function refreshStatus(){const [x,sx]=await Promise.all([api('autoStatus'),api('systemStatus')]);const r=resultOf(x)||{};byId('mAuto').textContent=i18nFormat(r.enabled?'common.on':'common.off');byId('mOnline').textContent=(r.running||0)+' / '+(r.target_online||0);byId('mOnlineLabel').textContent=gameMaxUser?i18nFormat('dashboard.online_max',{max:gameMaxUser}):i18nFormat('card.online_target');byId('mStore').textContent=(r.store_running||0)+' ('+(r.store_item_running||0)+' / '+(r.store_disjoint_running||0)+')';const s=resultOf(sx)||{};byId('robotUptimeHead').textContent=i18nFormat('dashboard.runtime',{uptime:uptime(s.robot_uptime_seconds)});const el=byId('mRobot');el.className='card good';el.querySelector('.v').textContent=Number(s.robot_cpu_percent||0).toFixed(1)+'% '+(s.robot_memory_mb||0)+'MB';el.querySelector('.k').textContent=i18nFormat('dashboard.robot_threads',{count:s.robot_threads||0})}
async function refreshScheduler(){try{const x=await api('schedulerStatus');const s=resultOf(x)||{};byId('sMode').textContent=s.mode||'-';byId('sOnline').textContent=i18nEnglishFormat('scheduler.attach_value',{rate:s.online_start_rate||0,batch:s.online_batch_size||0});byId('sStore').textContent=i18nEnglishFormat('scheduler.store_value',{running:s.store_running||0,target:s.store_target||0,concurrent:s.store_concurrent||0,probability:s.store_probability_percent||0});byId('sScale').textContent=i18nEnglishFormat('scheduler.scale_value',{up:s.scale_up_batch||0,down:s.scale_down_batch||0});byId('sPressure').textContent=i18nEnglishFormat('scheduler.pressure_value',{login:s.connecting||0,cpu:Number(s.cpu_percent||0).toFixed(1)});byId('sRelease').textContent=i18nEnglishFormat('scheduler.release_value',{breaker:s.breaker_release_batch||0,port:s.port_down_release_batch||0});const op=s.recent_operation?(' | '+i18nEnglishFormat('scheduler.operation_value',{operation:s.recent_operation,state:s.recent_operation_state||'',summary:s.recent_operation_summary||''}).trim()):'';byId('sReason').textContent=i18nEnglishFormat('scheduler.reason_value',{reason:s.reason||'-',running:s.running||0,target:s.target_online||0,idle:s.idle||0,port:s.game_port_ready?'ready':'down',breaker:s.breaker_active?'On':'Off',actors:[s.actor_idle||0,s.actor_assigned||0,s.actor_online||0,s.actor_running||0,s.actor_busy||0,s.actor_releasing||0].join('/')})+op}catch(e){byId('sMode').textContent='Error';byId('sReason').textContent=e.message}}
function uptime(sec){sec=Number(sec||0);const h=Math.floor(sec/3600),m=Math.floor((sec%3600)/60),s=sec%60;return h?h+':'+String(m).padStart(2,'0')+':'+String(s).padStart(2,'0'):m+':'+String(s).padStart(2,'0')}
async function refreshRobots(){lastRobotsRefresh=Date.now();const x=await api('robotsStatus',{count:1000});const r=resultOf(x)||{};currentRows=r.robots||[];const tb=document.querySelector('#tbl tbody');tb.textContent='';tb.classList.remove('bulk-selected');const frag=document.createDocumentFragment();for(const a of currentRows){const uid=String(a.uid||'');const tr=document.createElement('tr');if(selected.has(uid))tr.className='sel';const cb=document.createElement('input');cb.type='checkbox';cb.checked=selected.has(uid);appendCell(tr,cb);appendCell(tr,uid);appendCell(tr,text(a.cid));appendCell(tr,text(a.name));const actor=document.createElement('span');const deleting=a.operation==='cleanup';actor.className='pill '+(deleting?'warn':(a.actor_attached?'ok':''));actor.textContent=deleting?i18nFormat('status.deleting'):(a.actor_attached?('slot '+(a.actor_slot||'-')+' '+(a.actor_state||'')):i18nFormat('status.free'));actor.title=deleting?'cleanup running':(a.actor_busy?('busy '+(a.actor_busy_kind||'')):'');appendCell(tr,actor);const rs=a.robot_state||{};const bad=rs.actual_state==='error'||rs.actual_state==='disconnected'||rs.last_error;const state=document.createElement('span');state.className='pill '+(bad?'bad':(rs.phase==='executing'?'warn':'ok'));state.textContent=(rs.actual_state||'-')+' -> '+(rs.desired_state||'-');state.title='db '+(a.db_state||'-')+' phase '+(rs.phase||'-')+(rs.last_error?' error '+rs.last_error:'')+(a.operation?' op '+a.operation:'');appendCell(tr,state);[a.level,jobGrowName(a.job,a.grow),villageDisplay(a),a.area,a.x,a.y,uptime(a.uptime_seconds)].forEach(v=>appendCell(tr,text(v)));const store=(a.robot_type==3&&a.disjoint_active)?'disjoint':(a.store_display_ack?'item':((a.store_created||a.robot_type==2||a.robot_type==3)?'pending':''));const span=document.createElement('span');if(store){span.className='pill '+(store==='pending'?'warn':'ok');span.textContent=i18nEnglishFormat('status.'+store)}appendCell(tr,span);tr.onclick=e=>{tb.classList.remove('bulk-selected');if(e.target.tagName!=='INPUT')cb.checked=!cb.checked;cb.checked?selected.add(uid):selected.delete(uid);tr.className=selected.has(uid)?'sel':'';updateSelectedInfo()};frag.appendChild(tr)}tb.appendChild(frag);byId('listInfo').textContent=i18nFormat('robots.list_info',{shown:currentRows.length,total:r.total||currentRows.length,time:new Date().toLocaleTimeString()});updateSelectedInfo()}
function appendCell(tr,v){const td=document.createElement('td');if(v instanceof Node)td.appendChild(v);else td.textContent=v;tr.appendChild(td)}function selectedPayload(){const u=[...selected].map(Number);return u.length?{uids:u}:{count:Math.max(1,Number(byId('actionCount').value||1))}}function updateSelectedInfo(){byId('selectedInfo').textContent=i18nFormat('toolbar.selected',{count:selected.size});byId('checkAll').checked=currentRows.length>0&&currentRows.every(r=>selected.has(String(r.uid||'')))}
async function checkGame(){const x=await fetch('/api/game-port').then(r=>r.json());gameBlocked=!x.ok;gameMaxUser=Number(x.max_user_num||0);byId('mOnlineLabel').textContent=gameMaxUser?i18nFormat('dashboard.online_max',{max:gameMaxUser}):i18nFormat('card.online_target');const el=byId('mGame');el.className='card '+(x.ok?'good':'bad');el.querySelector('.v').textContent=i18nFormat(x.ok?'common.open':'common.closed');el.title=(x.error||x.addr||'');applyKeyGate()}
function portOnly(addr){const s=text(addr);const i=s.lastIndexOf(':');return i>=0?s.slice(i+1):s}
function serviceView(label,name,open,addr){const port=portOnly(addr)||'-';const state=i18nFormat(open?'common.open':'status.down');return {label,open,port,title:i18nText(name)+': '+state+' '+port}}
function renderServices(list){const el=byId('mMonitor');const allOpen=list.every(x=>x.open);el.className='card '+(allOpen?'good':'bad');el.querySelector('.v').innerHTML=list.map(x=>'<span class="svc" title="'+escapeHTML(x.title)+'"><span class="dot '+(x.open?'open':'closed')+'"></span>'+escapeHTML(x.label)+'</span>').join('');el.title=list.map(x=>x.title).join('\n')}
async function checkServices(){const [monitor,relay,market]=await Promise.all([fetch('/api/monitor-service').then(r=>r.json()).catch(e=>({ok:false,error:e.message})),fetch('/api/relay-service').then(r=>r.json()).catch(e=>({ok:false,error:e.message})),api('marketStatus').then(x=>resultOf(x)||{}).catch(e=>({services:{},error:e.message}))]);const services=market.services||{};const auction=services.auction||{},point=services.point||{};renderServices([serviceView('M',i18nFormat('ports.monitor'),!!monitor.ok,monitor.addr),serviceView('A',i18nFormat('ports.auction'),auction.status==='ready'&&!!auction.listening,auction.addr),serviceView('G',i18nFormat('market.gold'),point.status==='ready'&&!!point.listening,point.addr),serviceView('R',i18nFormat('ports.relay'),!!relay.ok,relay.addr)])}
async function refreshDatabase(){const capability=backendCapabilities.database;if(capability&&!capability.enabled){dbBlocked=false;const el=byId('mDB');el.className='card';el.querySelector('.v').textContent='N/A';el.title=capability.reason||'backend capability unavailable';applyKeyGate();return}try{const x=await api('databaseStatus');const r=resultOf(x)||{};dbBlocked=!r.ok;const el=byId('mDB');el.className='card '+(dbBlocked?'bad':'good');el.querySelector('.v').textContent=r.ok?i18nFormat('common.ok')+' '+(r.latency_ms||0)+'ms':i18nFormat('common.error');el.title=r.ok?(r.target||''):(r.error||i18nFormat('error.database_unavailable'));applyKeyGate()}catch(e){dbBlocked=true;applyKeyGate();const el=byId('mDB');el.className='card bad';el.querySelector('.v').textContent=i18nFormat('common.error');el.title=e.message}}
