function toggleAll(checked){const tb=document.querySelector('#tbl tbody');tb.classList.remove('bulk-selected');if(checked){currentRows.forEach(r=>selected.add(String(r.uid||'')))}else{selected.clear()}document.querySelectorAll('#tbl tbody tr').forEach(tr=>{const uid=tr.children[1]?tr.children[1].textContent:'';const on=selected.has(uid);tr.className=on?'sel':'';const cb=tr.querySelector('input[type=checkbox]');if(cb)cb.checked=on});updateSelectedInfo()}
function closeModal(){dangerousDeleteToken='';if(partyDebugTimer){clearTimeout(partyDebugTimer);partyDebugTimer=null}stopMarketKindsProgress();byId('modal').close()}function showModal(title,body,foot,style,translate=true){const m=byId('modal');m.className=style||'';byId('modalTitle').textContent=translate?i18nText(title):title;byId('modalBody').innerHTML=translate?i18nHTML(body):body;const footer=foot===undefined?'<button onclick="closeModal()">Close</button>':foot;byId('modalFoot').innerHTML=translate?i18nHTML(footer):footer;const saveButton=byId('modalSaveButton');if(saveButton){saveButton.style.display=style==='market'?'':'none';saveButton.textContent=marketText('Save and rebuild','保存并重建')}const closeButton=m.querySelector('.dlghead button:last-child');if(closeButton)closeButton.textContent=translate?i18nFormat('common.close'):'Close';if(!m.open)m.showModal()}
