async function submitAuto(forceStart){const shoutMin=Math.floor(Number(byId('autoShoutMin').value||0)),shoutMax=Math.floor(Number(byId('autoShoutMax').value||0));if(shoutMin<1||shoutMax<shoutMin||shoutMax>86400){toast(i18nFormat('result.failed',{action:i18nFormat('action.auto'),error:i18nFormat('validation.shout_interval')}));return}const enabled=forceStart===true||forceStart===null&&byId('autoEnabled').checked,follow=byId('followAccount'),followValue=follow.type==='checkbox'?(follow.checked?'enabled':''):String(follow.value||'').trim();const updates={'auto.auto_target_online_count':String(byId('autoTarget').value||20),'auto.auto_shout_interval_min_sec':String(shoutMin),'auto.auto_shout_interval_max_sec':String(shoutMax),'auto.auto_actions':String(enabled),'auto.auto_mail_notify':String(byId('autoMailNotify').checked),'follow.follow_account':followValue,'spawn.spawn_fixed':String(byId('spawnFixed').checked),'spawn.spawn_village':String(byId('spawnVillage').value||3),'spawn.spawn_area':String(byId('spawnArea').value||0)};closeModal();await guarded('Auto',async()=>{const config=await api('robotConfigUpdate',{updates});const auto=await api(enabled?'autoStart':'autoStop');setTimeout(refreshAll,1000);return {config,auto}})}
async function submitGamePort(){const payload={game_port:Math.floor(Number(byId('gamePort').value||0)),monitor_port:Math.floor(Number(byId('monitorPort').value||0)),auction_port:Math.floor(Number(byId('auctionPort').value||0)),point_port:Math.floor(Number(byId('pointPort').value||0)),relay_port:Math.floor(Number(byId('relayPort').value||0))};if([payload.game_port,payload.monitor_port,payload.auction_port,payload.point_port,payload.relay_port].some(p=>p<1||p>65535)){toast(i18nFormat('result.failed',{action:i18nFormat('operation.ports'),error:i18nFormat('validation.port_range')}));return}closeModal();if(busy)return;setBusy(true);try{const x=await fetch('/api/game-endpoint',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}).then(r=>r.json());writeLog(x);if(!x.ok)throw new Error(x.error||i18nFormat('error.save_ports_failed'));toast(x.message?i18nText(x.message):i18nFormat('message.saved_restart'));setTimeout(refreshAll,1000)}catch(e){writeLog({ok:false,error:e.message});toast(i18nFormat('result.failed',{action:i18nFormat('operation.ports'),error:e.message}))}finally{setBusy(false)}}
function renderPortsDialog(ports,notice=''){const body=(notice?'<div class="muted port-detect-notice">'+escapeHTML(notice)+'</div>':'')+'<div class="formgrid"><label>Game</label><input id="gamePort" type="number" min="1" max="65535" value="'+escapeHTML(ports.game||10011)+'"><label>Monitor</label><input id="monitorPort" type="number" min="1" max="65535" value="'+escapeHTML(ports.monitor||30303)+'"><label>Auction</label><input id="auctionPort" type="number" min="1" max="65535" value="'+escapeHTML(ports.auction||30803)+'"><label>Point</label><input id="pointPort" type="number" min="1" max="65535" value="'+escapeHTML(ports.point||30603)+'"><label>Relay</label><input id="relayPort" type="number" min="1" max="65535" value="'+escapeHTML(ports.relay||7200)+'"></div>';const foot='<button onclick="openServicePortsDialog()">'+i18nFormat('ports.detect')+'</button><button onclick="submitGamePort()">'+i18nFormat('ports.save')+'</button><button class="danger" onclick="restartRobot()">'+i18nFormat('ports.restart_short')+'</button>';showModal('Ports',body,foot,'ports')}
const legacyPortsMarkup=`const ports=endpoint.ports||{};const body='<div class="formgrid"><label>Game</label>`;
const legacyPortsFooter=`const foot='<button onclick="submitGamePort()">Save Ports</button>`;
async function openPortsDialog(){await guarded('Ports',async()=>{const endpoint=await fetch('/api/game-endpoint').then(r=>r.json());if(!endpoint.ok)throw new Error(endpoint.error||i18nFormat('error.read_endpoint_failed'));const ports=endpoint.ports||{};renderPortsDialog(ports)})}
async function openServicePortsDialog(){const values={game:byId('gamePort')?.value,monitor:byId('monitorPort')?.value,auction:byId('auctionPort')?.value,point:byId('pointPort')?.value,relay:byId('relayPort')?.value};try{setBusy(true);const x=await fetch('/api/service-ports').then(r=>r.json());if(!x.ok)throw new Error(x.error||i18nFormat('error.status_failed'));let body='<div class="muted port-detect-hint">'+escapeHTML(i18nFormat('ports.detect_hint'))+'</div><div class="port-detect-list">';for(const s of (x.services||[])){const candidates=s.candidates||[],configured=String(s.configured_port),matched=candidates.filter(c=>String(c.port)===configured),status=s.state==='matched'?i18nFormat('ports.detect_matched'):s.state==='mismatch'?i18nFormat('ports.detect_mismatch'):s.state==='multiple'?i18nFormat('ports.detect_multiple'):i18nFormat('ports.detect_not_running');body+='<div class="port-detect-row"><div><strong>'+escapeHTML(s.process)+'</strong><div class="muted">'+escapeHTML(status)+'</div></div><div class="port-detect-candidates">';if(!candidates.length)body+='<span class="muted">'+escapeHTML(i18nFormat('ports.detect_none'))+'</span>';else for(const c of candidates){const isMatched=String(c.port)===configured,disabled=s.state==='matched',checked=isMatched||(candidates.length===1&&!matched.length);body+='<label class="port-detect-candidate"><input type="radio" name="detect-'+escapeHTML(s.key)+'" value="'+escapeHTML(c.port)+'" '+(checked?'checked ':'')+(disabled?'disabled ':'')+'> '+escapeHTML(c.port)+' <span class="muted">'+escapeHTML(c.pid?'PID '+c.pid:'')+(isMatched?' '+escapeHTML(i18nFormat('ports.detect_matched')):'')+'</span></label>'}body+='</div></div>'}body+='</div>';showModal(i18nFormat('ports.detect_title'),body,'<button class="primary" onclick="applyDetectedPorts()">'+i18nFormat('ports.detect_apply')+'</button>','ports-detect')}catch(e){toast(i18nFormat('result.failed',{action:i18nFormat('ports.detect_title'),error:e.message}));renderPortsDialog(values)}finally{setBusy(false)}}
function applyDetectedPorts(){const values={game:byId('gamePort')?.value,monitor:byId('monitorPort')?.value,auction:byId('auctionPort')?.value,point:byId('pointPort')?.value,relay:byId('relayPort')?.value};let count=0;document.querySelectorAll('.port-detect-candidate input:checked:not(:disabled)').forEach(radio=>{const key=radio.name.slice(7);values[key]=radio.value;count++});renderPortsDialog(values,count?i18nFormat('ports.detect_applied'):'')}
async function openCompatDialog(){await guarded('Compat',async()=>{const x=await fetch('/api/compat').then(r=>r.json());if(!x.ok)throw new Error(x.error||i18nFormat('error.read_compat_failed'));const s=x.result||{};const msg=s.message?('<div class="muted" style="grid-column:1/-1">'+escapeHTML(i18nText(s.message))+'</div>'):'';const body='<div class="formgrid"><label>Guard</label><label><input id="mailboxBadNodeGuard" type="checkbox" '+(s.desired_enabled?'checked':'')+'> Mailbox cleanup</label><label>State</label><div>'+escapeHTML(i18nText(s.state||'-'))+'</div><label>Game</label><div>PID '+escapeHTML(s.pid||'-')+' / '+escapeHTML(s.port||'-')+'</div><div class="muted" style="grid-column:1/-1">DNF 70 only. Changes are applied to the running game process when available.</div>'+msg+'</div>';showModal('70 Compat',body,'<button onclick="closeModal()">Cancel</button><button class="primary" onclick="submitCompat()">Save</button>','compact')})}
async function submitCompat(){const enabled=!!byId('mailboxBadNodeGuard')?.checked;closeModal();await guarded('Save compatibility',async()=>{const x=await fetch('/api/compat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mailbox_bad_node_guard:enabled})}).then(r=>r.json());if(!x.ok)throw new Error(x.error||i18nFormat('error.save_compat_failed'));toast(x.message?i18nText(x.message):i18nFormat('message.compat_applied'));return x})}
async function restartRobot(){if(busy)return;setBusy(true);try{const x=await fetch('/api/restart-robot',{method:'POST'}).then(r=>r.json());writeLog(x);if(!x.ok)throw new Error(x.error||i18nFormat('error.restart_failed'));toast(x.message?i18nText(x.message):i18nFormat('message.restart_queued'));setTimeout(()=>location.reload(),5000)}catch(e){writeLog({ok:false,error:e.message});toast(i18nFormat('result.failed',{action:i18nFormat('operation.restart'),error:e.message}));setBusy(false)}}
function keyStateText(r){if(r.key_state==='default'||r.using_default)return i18nFormat('key.project_default');if(r.key_state==='user')return i18nFormat('key.user');if(r.key_state==='invalid')return i18nFormat('key.invalid');if(r.key_state==='missing')return i18nFormat('key.missing');return r.key_state||'-'}
function keyCompleteText(r){return i18nFormat(r.game_valid?'common.complete':'common.incomplete')}
async function openKeyDialog(){await guarded('Key',async()=>{const x=await api('keypairStatus');const r=resultOf(x)||{};const fp=r.fingerprint?String(r.fingerprint).slice(0,16)+'...':'-';const body='<div class="formgrid"><label>Current key</label><div>'+escapeHTML(keyStateText(r))+'</div><label>Completeness</label><div>'+escapeHTML(keyCompleteText(r))+'</div><label>Game directory</label><div>'+escapeHTML(r.game_valid?'Complete':'Missing or invalid')+'</div><label>Config directory</label><div>'+escapeHTML(r.config_valid?'Complete':'Missing or invalid')+'</div><label>Bundled default</label><div>'+escapeHTML(r.default_valid?'Available':'Unavailable')+'</div><label>Fingerprint</label><div>'+escapeHTML(fp)+'</div><label>Game private</label><div class="muted">'+escapeHTML(r.game_private||'-')+'</div><label>Game public</label><div class="muted">'+escapeHTML(r.game_public||'-')+'</div></div>';showModal('RSA Key',body,'<button onclick="closeModal()">Close</button><button onclick="downloadDefaultKeypair()">Download Bundled Default Key</button><button class="primary" onclick="releaseDefaultKeypair()">Release Bundled Default Key</button>')})}
async function openMaxDialog(){await guarded('Read max user',async()=>{const x=await fetch('/api/max-user').then(r=>r.json());if(!x.ok)throw new Error(x.error||i18nFormat('error.read_max_failed'));showModal('Max Online','<div class="formgrid"><label>Max online</label><input id="maxUserNum" type="number" min="1" max="600" value="'+escapeHTML(Math.min(600,x.max_user_num||600))+'" oninput="clampMaxUserInput(this)"><label>Config files</label><div>'+escapeHTML(i18nFormat('max.files',{count:(x.files||[]).length}))+'</div><div class="muted" style="grid-column:1/-1">Updates max_user_num in all cfg files under the df_game_r cfg directory.<br>Maximum is 600. Changes take effect after restarting /root/run.</div></div>','<button onclick="closeModal()">Cancel</button><button class="primary" onclick="submitMaxUser()">Save</button>')})}
function clampMaxUserInput(input){if(Number(input?.value)>600)input.value='600'}
async function submitMaxUser(){const input=byId('maxUserNum');clampMaxUserInput(input);const n=Math.floor(Number(input.value||0));if(!n||n<1){toast(i18nFormat('result.failed',{action:i18nFormat('operation.max'),error:i18nFormat('validation.positive_number')}));return}closeModal();if(busy)return;setBusy(true);try{const x=await fetch('/api/max-user',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({max_user_num:n})}).then(r=>r.json());if(!x.ok)throw new Error(x.error||i18nFormat('error.update_max_failed'));gameMaxUser=n;byId('mOnlineLabel').textContent=i18nFormat('dashboard.online_max',{max:n});writeLog(x);toast(x.message?i18nText(x.message):i18nFormat('max.files',{count:(x.files||[]).length}));setTimeout(refreshAll,1000)}catch(e){writeLog({ok:false,error:e.message});toast(i18nFormat('result.failed',{action:i18nFormat('operation.max'),error:e.message}))}finally{setBusy(false)}}
async function openScriptDialog(){try{const s=await fetch('/api/server-script').then(r=>r.json());const state=s.error?(i18nFormat('common.failed')+': '+s.error):(s.started_at?i18nFormat('script.submitted',{command:s.action||s.script||'',time:s.started_at}):i18nFormat('common.idle'));showModal('Server Scripts','<div class="formgrid"><label>Last command</label><div>'+escapeHTML(state)+'</div><label>/root/run</label><div>Start game services</div><label>/root/stop</label><div>Stop game services</div></div>','<button onclick="closeModal()">Cancel</button><button class="primary" onclick="submitServerScript(&quot;run&quot;)">Run /root/run</button><button class="danger" onclick="submitServerScript(&quot;stop&quot;)">Run /root/stop</button>')}catch(e){toast(i18nFormat('result.failed',{action:i18nFormat('operation.script_status'),error:e.message}))}}
async function submitServerScript(action){closeModal();const button=byId('scriptButton');if(button)button.disabled=true;try{const x=await fetch('/api/server-script',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action})}).then(r=>r.json());writeLog(x);if(!x.ok)throw new Error(x.error||i18nFormat('error.script_failed'));toast(i18nFormat('result.started',{action:x.script||action}));setTimeout(refreshAll,1000)}catch(e){writeLog({ok:false,error:e.message});toast(i18nFormat('result.failed',{action:i18nFormat('operation.script'),error:e.message}))}finally{if(button)button.disabled=false}}
async function openMarketDialog(){await guarded('Market',async()=>{const x=await api('marketStatus');showMarketDialog(resultOf(x)||{});return x})}
function marketSection(title,rows){return '<div class="formsection"><h4>'+escapeHTML(title)+'</h4><div class="formgrid">'+rows+'</div></div>'}
function marketDetailsSection(title,content){return '<details class="formsection market-rule-details"><summary><span>'+escapeHTML(title)+'</span><span class="market-rule-chevrons" aria-hidden="true"><i></i><i></i></span></summary><article class="market-rule-article">'+content+'</article></details>'}
function marketDetailsFormSection(title,rows){return marketDetailsSection(title,'<div class="formgrid">'+rows+'</div>')}
function marketText(en,zh){return i18nLanguage()==='zh'?zh:en}
function marketRuleSummary(){
 const rules=[
  [marketText('Data sources and boundary','数据来源与边界'),marketText('Automatic listing candidates are built from the intersection of the PVF auction catalog and the currently deployed iteminfo.dat, so an item must exist in both sources before it can enter the workflow. Exporting PVF data refreshes the equipment and stackable catalogs. Saving the regular Market settings only changes listing and recycling rules; it does not export, replace, or publish ItemInfo.','自动上架候选取自 PVF 拍卖目录与当前已发布的 iteminfo.dat 的交集，物品必须同时存在于两处，才会进入后续流程。导出 PVF 数据时会刷新装备与堆叠物品目录。普通的拍卖行设置保存只会修改上架与回收规则，不会导出、替换或发布 ItemInfo。')],
  [marketText('Saving and rebuilding','保存与重建'),marketText('After Save is confirmed, the system first validates the current ItemInfo and the submitted values. If automatic operation is running, it is paused temporarily and resumed after rebuilding. The new rules are then applied, existing Robot auction listings and system creature listings are cleared, the auction work queues are reset, and the auction service is restarted when it was already running. Finally, one restock round is executed with the new rules. This rebuild still does not export or publish ItemInfo.','确认保存后，系统会先校验当前 ItemInfo 和提交的配置值。若自动运行已经开启，会先临时停止，并在重建结束后恢复。随后应用新规则，清理已有的机器人拍卖商品和系统宠物商品，重置拍卖任务队列；如果拍卖服务原本正在运行，还会重启该服务。最后按新规则执行一轮补货。整个重建过程仍然不会导出或发布 ItemInfo。')],
  [marketText('Filtering order','过滤顺序'),marketText('Every candidate first passes mandatory safety checks: invalid, blocked, expired, avatar, client-incompatible, and otherwise unsafe item types are always excluded. Only after that does the allowlist take effect; it can override the blocklist, rarity, equipment-level, and trade-policy filters, but never the mandatory safety checks. Equipment and other items use their own rarity and trade policies. Strict policy rejects items marked as bound, non-tradeable, or unavailable for auction; permissive policy relaxes those trade flags where the service can safely handle them.','每个候选物品都会先经过强制安全检查：无效、禁止、过期、时装、客户端不兼容及其他不安全类型始终排除。之后才处理白名单；白名单可以覆盖黑名单、稀有度、装备等级和交易策略过滤，但不能绕过强制安全检查。装备和其他物品分别使用各自的稀有度与交易策略。严格策略会排除标记为绑定、不可交易或不可拍卖的物品；宽松策略只在服务可安全处理的范围内放宽这些交易标记。')],
  [marketText('Restock planning','补货规划'),marketText('Each restock round reads the current Robot and system stock from the database. An item is listed only when its item ID has no existing system stock at all; a partially stocked ID is not topped up. Equipment is created as one piece per listing using the configured record-count range. Random upgrade values are assigned only to supported weapon, armor, accessory, support-equipment, and magic-stone slots; titles, creatures, artifacts, avatars, and unknown slots receive no normal upgrade. Stackables choose from the configured stack sizes, are capped by the PVF stack limit, and are split into multiple records when necessary. Seller owner IDs rotate according to the configured owner policy.','每轮补货都会先从数据库读取当前机器人与系统库存。只有某个物品 ID 完全没有系统库存时才会上架；已有部分库存的 ID 不会继续补足。装备每条记录上架 1 件，并按配置的记录数量范围生成。只有受支持的武器、防具、首饰、辅助装备和魔法石槽位会随机生成强化值；称号、宠物、宠物装备、时装和未知槽位不会获得常规强化。堆叠物品从配置的堆叠数量中选择，同时受 PVF 堆叠上限约束，必要时拆成多条记录。卖家角色 ID 会按配置的归属策略轮换。')],
  [marketText('Price calculation','价格计算'),marketText('An enabled item-specific price range has the highest priority. Otherwise, every item uses its category unit-price range, and rarity, level, and a valid PVF value signal determine the position inside that range. Equipment follows the same category calculation, then additionally applies its equipment multiplier and supported upgrade premium. Final fluctuation is clamped to the category range for ordinary categories, while equipment is clamped to its final maximum unit price.','启用物品独立价格范围时优先使用该范围。否则，所有物品都使用所属分类的单价范围，稀有度、等级和有效 PVF 价值决定其在范围内的位置。装备采用同样的分类计算方式，再额外应用装备倍率和受支持的强化加价。普通分类的最终随机浮动不会突破分类范围，装备不会突破最终单价上限。')],
  [marketText('Execution and confirmation','执行与确认'),marketText('Planned listing actions are limited by the effective action count, dispatched with the configured maximum concurrency, and can continue after an individual action fails. A successful send does not by itself prove that stock exists: after restock, the system checks the database again and confirms which item IDs actually appeared. The operation result and logs distinguish planned, executed, failed, and database-confirmed outcomes, which should be used when diagnosing missing stock.','规划好的上架动作会先受有效动作数量限制，再按配置的最大并发执行；单个动作失败时可继续处理后续动作。发送成功本身并不等于库存已经存在：补货后系统会再次查询数据库，确认哪些物品 ID 实际写入。操作结果和日志会区分计划、已执行、失败及数据库已确认等状态，排查缺货时应以这些结果为准。')],
  [marketText('Automatic recycling','自动回收'),marketText('When the collector is enabled, it scans eligible player buyout listings. If item price-range filtering is disabled, eligible listings continue without price classification. If enabled, equipment uses the listing record price, while stackables use total price divided by quantity as their unit price. An enabled item-specific range is checked first; otherwise the collector uses the same value-model bounds as restock. In-range and out-of-range listings are sampled independently with their configured probabilities, then action-count and concurrency limits are applied. Robot listings that no longer satisfy the current filters may also be recycled as rules change.','启用自动回收后，系统会扫描符合条件的玩家一口价商品。关闭物品价格范围过滤时，符合条件的商品不会再按价格分类；启用后，装备按单条记录价格判断，堆叠物品以总价除以数量作为单价。已启用的物品独立价格范围优先，否则回收会使用与补货相同的价值模型区间。范围内和范围外商品分别按各自概率独立抽取，之后再应用动作数量和并发限制。规则变化后，不再符合当前过滤条件的机器人商品也可能被回收。')],
  [marketText('Automatic operation and recovery','自动运行与恢复'),marketText('Automatic mode processes the configured markets repeatedly at the configured interval, applying the effective action and concurrency limits to each cycle. The market policy watches candidate counts, database item-kind growth, zero-stock conditions, and action failures. When progress stalls or repeated failures occur, it can rebuild work queues, reduce send pressure, or restart the auction service before continuing. These recovery actions are intended to restore progress; their outcomes remain visible in operation results and logs.','自动模式会按配置的时间间隔循环处理已配置市场，并在每轮应用有效的动作数量和并发限制。市场策略会监控候选数量、数据库商品种类增长、零库存状态以及动作失败情况。进度停滞或连续失败时，系统可能重建任务队列、降低发送压力，或重启拍卖服务后继续运行。这些恢复动作只用于恢复处理进度，执行结果仍会记录在操作结果和日志中。')],
  [marketText('Manual actions','手动操作'),marketText('Restock runs one missing-stock fill round, and Collect runs one player-listing recycle round. Clear Stock deletes Robot and system market listings. ItemInfo is a separate publishing workflow: it exports ItemInfo from the current PVF data, clears Robot listings, publishes the generated file, and then restarts the auction and gold services. Memory Patch adjusts supported auction search limits in the running service, while Auction Guard installs the compatibility guard used by supported auction searches; these specialized actions are independent of saving normal Market settings.','“补货”执行一轮缺失库存填充，“回收”执行一轮玩家商品回收。“清空库存”会删除机器人与系统市场商品。“ItemInfo”是独立的发布流程：根据当前 PVF 数据导出 ItemInfo，清理机器人商品，发布生成的文件，然后重启拍卖与金币寄售服务。“内存补丁”用于调整运行中服务支持的拍卖搜索限制，“拍卖保护”用于安装受支持拍卖搜索所需的兼容保护；这些专项操作与普通拍卖行设置保存相互独立。')]
 ];
 return rules.map(rule=>'<section><h5>'+escapeHTML(rule[0])+'</h5><p>'+escapeHTML(rule[1])+'</p></section>').join('')
}
function marketNumber(id,value,min,max,step){return '<input id="'+id+'" type="number" min="'+min+'" max="'+max+'" step="'+(step||1)+'" value="'+escapeHTML(value)+'">'}
function marketField(control,unit,size){return '<div class="market-field'+(size?' market-field-'+size:'')+'">'+control+(unit?'<span>'+escapeHTML(unit)+'</span>':'')+'</div>'}
function marketRange(left,right,unit,size){return '<div class="market-range'+(size?' market-range-'+size:'')+'">'+left+'<span>～</span>'+right+(unit?'<span>'+escapeHTML(unit)+'</span>':'')+'</div>'}
function marketPercent(value){return Math.round(Number(value||0)*10000)/100}
const defaultEquipmentRarityScoreCurve='(0,0%);(1,20%);(2,40%);(3,60%);(4,80%);(5,100%);(6,100%);(7,100%);(8,100%);(9,100%)';const marketCategoryDefaults={equipment:{min_price:10000,max_price:50000000,rarity_weight:.4,rarity_score_curve:defaultEquipmentRarityScoreCurve,level_weight:.35,pvf_weight:.25},title:{min_price:100000,max_price:10000000,rarity_weight:.4,level_weight:.2,pvf_weight:.4},card:{min_price:20000,max_price:20000000,rarity_weight:.4,level_weight:.2,pvf_weight:.4},creature:{min_price:100000,max_price:20000000,rarity_weight:.4,level_weight:.2,pvf_weight:.4},artifact:{min_price:10000,max_price:5000000,rarity_weight:.4,level_weight:.2,pvf_weight:.4},bead:{min_price:10000,max_price:5000000,rarity_weight:.4,level_weight:.2,pvf_weight:.4},recipe:{min_price:1000,max_price:500000,rarity_weight:.4,level_weight:.2,pvf_weight:.4},material:{min_price:100,max_price:50000,rarity_weight:.4,level_weight:.2,pvf_weight:.4},consumable:{min_price:200,max_price:30000,rarity_weight:.4,level_weight:.2,pvf_weight:.4},puppet:{min_price:5000,max_price:200000,rarity_weight:.4,level_weight:.2,pvf_weight:.4},other:{min_price:100,max_price:100000,rarity_weight:.4,level_weight:.2,pvf_weight:.4}};
function marketPriceRuleFields(key,rule){const prefix='marketPriceRule_'+key+'_',curve=rule.rarity_score_curve||defaultEquipmentRarityScoreCurve;return '<div class="formgrid"><label>'+marketText('Unit price range','单价范围')+'</label>'+marketRange(marketNumber(prefix+'min',rule.min_price,1,2000000000,1),marketNumber(prefix+'max',rule.max_price,1,2000000000,1),marketText('gold','金币'),'price')+'<label>'+marketText('Rarity weight','稀有度权重')+'</label>'+marketField(marketNumber(prefix+'rarity',marketPercent(rule.rarity_weight),0,10000,.1),'%','short')+(key==='equipment'?'<label>'+marketText('Rarity weight distribution','稀有度权重内部分布')+'</label>'+marketField('<input id="'+prefix+'curve" value="'+escapeHTML(curve)+'" placeholder="(0,0%);(1,20%);(2,40%);(3,60%);(4,80%);(5,100%);(6,100%);(7,100%);(8,100%);(9,100%)" onblur="try{validateMarketRarityScoreCurve(this.value)}catch(e){toast(e.message);this.focus()}">'): '')+'<label>'+marketText('Level weight','等级权重')+'</label>'+marketField(marketNumber(prefix+'level',marketPercent(rule.level_weight),0,10000,.1),'%','short')+'<label>'+marketText('PVF value weight','PVF 价值权重')+'</label>'+marketField(marketNumber(prefix+'pvf',marketPercent(rule.pvf_weight),0,10000,.1),'%','short')+'</div>'}
function marketEquipmentExtras(restock){return '<div class="formgrid market-equipment-extras"><label>'+marketText('Equipment price multiplier','装备价格倍率')+'</label>'+marketRange(marketNumber('marketEquipmentMultiplierMin',restock.equipment_multiplier_min??1,.01,100,.01),marketNumber('marketEquipmentMultiplierMax',restock.equipment_multiplier_max??2,.01,100,.01),marketText('times','倍'),'short')+'<label>'+marketText('Upgrade level','强化等级')+'</label>'+marketRange(marketNumber('marketUpgradeMin',restock.upgrade_min??7,0,31,1),marketNumber('marketUpgradeMax',restock.upgrade_max??13,0,31,1),'','short')+'<label>'+marketText('Upgrade price rate (nonlinear)','强化加价率（非线性）')+'</label>'+marketField(marketNumber('marketUpgradeRate',marketPercent(restock.upgrade_price_rate??.08),0,1000,.1),'%','short')+'<label>'+marketText('Final maximum unit price','最终单价上限')+'</label>'+marketField(marketNumber('marketEquipmentFinalMaxPrice',restock.equipment_final_max_price??200000000,1,2000000000,1),marketText('gold','金币'),'price')+'</div>'}
function marketCommonPriceSettings(restock){return '<label>'+marketText('Final price fluctuation','最终价格浮动')+'</label>'+marketRange(marketNumber('marketRandLow',marketPercent(restock.rand_low??.95),.01,10000,.1),marketNumber('marketRandHigh',marketPercent(restock.rand_high??1.05),.01,10000,.1),'%','short')}
function marketCategoryPriceRules(restock){const labels={equipment:marketText('Equipment','装备'),title:marketText('Titles','称号'),card:marketText('Cards','卡片'),creature:marketText('Creatures','宠物'),artifact:marketText('Artifacts','宠物装备'),bead:marketText('Beads','宝珠'),recipe:marketText('Recipes','设计图'),material:marketText('Materials','材料'),consumable:marketText('Potions and consumables','药剂与消耗品'),puppet:marketText('Puppets','人偶'),other:marketText('Other / Unclassified','其他 / 未分类')},rules=restock.category_price_rules||{};return Object.keys(labels).map(key=>{const rule={...marketCategoryDefaults[key],...(rules[key]||{})},extras=key==='equipment'?marketEquipmentExtras(restock):'';return '<details class="market-details"><summary>'+escapeHTML(labels[key])+' · '+Number(rule.min_price).toLocaleString()+' ～ '+Number(rule.max_price).toLocaleString()+'</summary>'+marketPriceRuleFields(key,rule)+extras+'</details>'}).join('')}
function showMarketDialog(s){
 const restock=s.restock||{},collector=s.collector||{},services=s.services||{},auction=services.auction||{},point=services.point||{};
 const equipmentRarities=normalizeRarityDigits(restock.equipment_allowed_rarities??'012345'),otherRarities=normalizeRarityDigits(restock.other_allowed_rarities??'012345');
 const policyOptions=(id,value)=>'<select class="market-policy-select" id="'+id+'"><option value="permissive" '+(value!=='strict'?'selected':'')+'>'+marketText('Permissive','宽松')+'</option><option value="strict" '+(value==='strict'?'selected':'')+'>'+marketText('Strict','严格')+'</option></select>';
 let body=marketSection(marketText('Runtime status','运行状态'),'<label>'+marketText('Automatic','自动运行')+'</label><div>'+escapeHTML(i18nFormat(s.auto_running?'common.running':'common.stopped'))+'</div><label>'+marketText('Auction','拍卖行')+'</label><div>'+escapeHTML(auction.status||'-')+'</div><label>'+marketText('Gold','金币寄售')+'</label><div>'+escapeHTML(point.status||'-')+'</div><label>'+marketText('Kinds (actual / expected)','种类（实际 / 预期）')+'</label><div id="marketKindsProgress">- / -</div>');
 body+=marketSection(marketText('Listing filters','上架过滤'),'<label>'+marketText('Equipment rarities (0-9)','装备稀有度（0-9）')+'</label>'+marketField('<input id="marketEquipmentRarities" inputmode="numeric" maxlength="10" pattern="[0-9]*" placeholder="012345" value="'+escapeHTML(equipmentRarities)+'" oninput="sanitizeMarketAllowedRarities(this)">')+'<label>'+marketText('Equipment policy','装备策略')+'</label>'+policyOptions('marketEquipmentTradePolicy',restock.equipment_trade_policy)+'<label>'+marketText('Other rarities (0-9)','其他物品稀有度（0-9）')+'</label>'+marketField('<input id="marketOtherRarities" inputmode="numeric" maxlength="10" pattern="[0-9]*" placeholder="012345" value="'+escapeHTML(otherRarities)+'" oninput="sanitizeMarketAllowedRarities(this)">')+'<label>'+marketText('Other policy','其他物品策略')+'</label>'+policyOptions('marketOtherTradePolicy',restock.other_trade_policy)+'<label>'+marketText('Blocked item IDs','屏蔽物品 ID')+'</label>'+marketField('<input id="marketBlockedItemIDs" placeholder="1,2,3,8-50,55" value="'+escapeHTML(formatBlockedItemIDs(restock.blocked_item_ids||[]))+'">')+'<label>'+marketText('Allowed item IDs','物品 ID 白名单')+'</label>'+marketField('<input id="marketAllowedItemIDs" placeholder="1,2,3,8-50,55" value="'+escapeHTML(formatAllowedItemIDs(restock.allowed_item_ids||[]))+'">')+'<label>'+marketText('Equipment level','装备等级')+'</label>'+marketRange(marketNumber('marketEquipmentLevelMin',restock.equipment_level_min??0,0,999,1),marketNumber('marketEquipmentLevelMax',restock.equipment_level_max??0,0,999,1),'','short'));
 body+=marketSection(marketText('Generation','生成设置'),'<label>'+marketText('Equipment quantity','装备数量')+'</label>'+marketRange(marketNumber('marketEquipmentQtyMin',restock.equipment_qty_min??2,1,10000,1),marketNumber('marketEquipmentQtyMax',restock.equipment_qty_max??5,1,10000,1),'','short')+'<label>'+marketText('Stack sizes','材料堆叠数量')+'</label>'+marketField('<input id="marketStackSizes" value="'+escapeHTML((restock.stack_sizes||[500,1000,2000]).join(','))+'">'));
 body+=marketSection(marketText('Category unit-price ranges','分类单价范围'),marketCommonPriceSettings(restock)+marketCategoryPriceRules(restock));
 body+=marketSection(marketText('Recycle policy','回收策略'),'<label>'+marketText('Collector','自动回收')+'</label><label><input id="marketCollectorEnabled" type="checkbox" '+(collector.enabled!==false?'checked':'')+'> '+marketText('Enabled','启用')+'</label><label>'+marketText('Item price ranges','物品独立价格范围')+'</label><label><input id="marketPriceRangeEnabled" type="checkbox" '+(collector.price_range_enabled?'checked':'')+'> '+marketText('Enabled','启用')+'</label><label>'+marketText('In-range probability','范围内回收概率')+'</label>'+marketField(marketNumber('marketInRangeProbability',marketPercent(collector.in_range_probability??0.8),0,100,0.1),'%','short')+'<label>'+marketText('Out-of-range probability','范围外回收概率')+'</label>'+marketField(marketNumber('marketOutRangeProbability',marketPercent(collector.out_of_range_probability??0.05),0,100,0.1),'%','short'));
 body+=marketDetailsSection(marketText('Rule details','规则说明'),marketRuleSummary());
 const foot='<div class="market-actions"><button title="Start market auto loop" class="primary" onclick="submitMarketStart()">On</button><button title="Stop market auto loop" onclick="submitMarketStop()">Off</button><button title="Fill missing market listings" onclick="submitMarketRestock()">Restock</button><button title="Buy back player buyout listings" onclick="submitMarketCollect()">Collect</button><button class="danger" title="Delete robot market listings from database" onclick="submitMarketClearStock()">Clear Stock</button><button class="danger" title="Export PVF iteminfo.dat, delete robot listings, release dat, then restart auction and gold services" onclick="submitMarketItemInfo()">ItemInfo</button><button class="danger" title="Patch running auction memory for level and refine search limits" onclick="submitMarketMemoryPatch()">Memory Patch</button><button class="danger" title="Install a safe dp2 auction search hook while preserving socket data" onclick="submitMarketAuctionGuard()">Auction Guard</button></div>';
 showModal('Market',body,foot,'market');startMarketKindsProgress()
}
function stopMarketKindsProgress(){if(marketKindsTimer){clearTimeout(marketKindsTimer);marketKindsTimer=null}marketKindsExpected=null}
function marketKindsDialogOpen(){const modal=byId('modal');return !!(modal&&modal.open&&modal.classList.contains('market')&&byId('marketKindsProgress'))}
function startMarketKindsProgress(){stopMarketKindsProgress();marketKindsTimer=setTimeout(()=>refreshMarketKindsProgress(true),0)}
async function refreshMarketKindsProgress(includeExpected){if(!marketKindsDialogOpen())return;marketKindsTimer=null;const el=byId('marketKindsProgress');try{const x=await api('marketKindsProgress',{include_expected:!!includeExpected}),r=resultOf(x)||{};if(r.expected!==undefined&&r.expected!==null)marketKindsExpected=Number(r.expected);const actual=Number(r.actual);el.textContent=(Number.isFinite(actual)?actual:'-')+' / '+(Number.isFinite(marketKindsExpected)?marketKindsExpected:'-');el.title=''}catch(e){if(el){el.textContent='- / '+(Number.isFinite(marketKindsExpected)?marketKindsExpected:'-');el.title=e.message}}finally{if(marketKindsDialogOpen())marketKindsTimer=setTimeout(()=>refreshMarketKindsProgress(false),5000)}}
function marketNumeric(id,fallback,min,max){let value=Number(byId(id)?.value);if(!Number.isFinite(value))value=fallback;if(min!==undefined)value=Math.max(min,value);if(max!==undefined)value=Math.min(max,value);return value}
function marketFormPayload(){
 let levelMin=Math.floor(marketNumeric('marketEquipmentLevelMin',0,0,999)),levelMax=Math.floor(marketNumeric('marketEquipmentLevelMax',0,0,999));if(levelMax>0&&levelMax<levelMin)levelMax=levelMin;
 let qtyMin=Math.floor(marketNumeric('marketEquipmentQtyMin',2,1,10000)),qtyMax=Math.floor(marketNumeric('marketEquipmentQtyMax',5,1,10000));if(qtyMax<qtyMin)qtyMax=qtyMin;
 let upgradeMin=Math.floor(marketNumeric('marketUpgradeMin',7,0,31)),upgradeMax=Math.floor(marketNumeric('marketUpgradeMax',13,0,31));if(upgradeMax<upgradeMin)upgradeMax=upgradeMin;
 let randLow=marketNumeric('marketRandLow',95,0.01,10000)/100,randHigh=marketNumeric('marketRandHigh',105,0.01,10000)/100;if(randHigh<randLow)randHigh=randLow;
 const stackSizes=String(byId('marketStackSizes')?.value||'').split(',').map(x=>Math.floor(Number(x.trim()))).filter(x=>Number.isFinite(x)&&x>0);
 const blockedItemIDExpression=parseBlockedItemIDExpression(byId('marketBlockedItemIDs')?.value||'');
 const allowedItemIDExpression=parseAllowedItemIDExpression(byId('marketAllowedItemIDs')?.value||'');
 const readRule=key=>{const prefix='marketPriceRule_'+key+'_',min=Math.floor(marketNumeric(prefix+'min',1,1,2000000000)),max=Math.floor(marketNumeric(prefix+'max',min,1,2000000000)),rule={min_price:min,max_price:Math.max(min,max),rarity_weight:marketNumeric(prefix+'rarity',40,0,10000)/100,level_weight:marketNumeric(prefix+'level',20,0,10000)/100,pvf_weight:marketNumeric(prefix+'pvf',40,0,10000)/100};if(key==='equipment')rule.rarity_score_curve=String(byId(prefix+'curve')?.value||defaultEquipmentRarityScoreCurve).trim();return rule};
 const categoryPriceRules={};for(const key of Object.keys(marketCategoryDefaults))categoryPriceRules[key]=readRule(key);let equipmentMultiplierMin=marketNumeric('marketEquipmentMultiplierMin',1,.01,100),equipmentMultiplierMax=marketNumeric('marketEquipmentMultiplierMax',2,.01,100);if(equipmentMultiplierMax<equipmentMultiplierMin)equipmentMultiplierMax=equipmentMultiplierMin;
 return {equipment_allowed_rarities:normalizeRarityDigits(byId('marketEquipmentRarities')?.value||''),other_allowed_rarities:normalizeRarityDigits(byId('marketOtherRarities')?.value||''),equipment_trade_policy:byId('marketEquipmentTradePolicy')?.value||'permissive',other_trade_policy:byId('marketOtherTradePolicy')?.value||'permissive',blocked_item_id_expression:blockedItemIDExpression,allowed_item_id_expression:allowedItemIDExpression,equipment_level_min:levelMin,equipment_level_max:levelMax,equipment_qty_min:qtyMin,equipment_qty_max:qtyMax,stack_sizes:stackSizes.length?stackSizes:[500,1000,2000],upgrade_min:upgradeMin,upgrade_max:upgradeMax,upgrade_price_rate:marketNumeric('marketUpgradeRate',8,0,1000)/100,rand_low:randLow,rand_high:randHigh,category_price_rules:categoryPriceRules,equipment_multiplier_min:equipmentMultiplierMin,equipment_multiplier_max:equipmentMultiplierMax,equipment_final_max_price:Math.floor(marketNumeric('marketEquipmentFinalMaxPrice',200000000,1,2000000000)),collector_enabled:!!byId('marketCollectorEnabled')?.checked,price_range_enabled:!!byId('marketPriceRangeEnabled')?.checked,in_range_probability:marketNumeric('marketInRangeProbability',80,0,100)/100,out_of_range_probability:marketNumeric('marketOutRangeProbability',5,0,100)/100}
}
function parseMarketItemIDExpression(value,nameEn,nameZh){const tokens=String(value??'').trim().split(/[\s,，]+/).filter(Boolean),ranges=[];for(const token of tokens){const parts=token.split('-');if(parts.length>2)throw new Error(marketText('Invalid '+nameEn+' range: ',nameZh+'范围格式错误：')+token);const start=Number(parts[0]),end=parts.length===2?Number(parts[1]):start;if(!Number.isInteger(start)||!Number.isInteger(end)||start<=0||end<start||end>4294967295)throw new Error(marketText('Invalid '+nameEn+' or range: ',nameZh+'或范围无效：')+token);ranges.push([start,end])}ranges.sort((a,b)=>a[0]-b[0]||a[1]-b[1]);const merged=[];for(const range of ranges){const last=merged[merged.length-1];if(last&&range[0]<=last[1]+1)last[1]=Math.max(last[1],range[1]);else merged.push(range.slice())}let count=0;for(const range of merged){count+=range[1]-range[0]+1;if(count>100000)throw new Error(marketText(nameEn+' may contain at most 100000 IDs.',nameZh+'展开后最多允许 100000 个。'))}return merged.map(x=>x[0]===x[1]?String(x[0]):x[0]+'-'+x[1]).join(',')}
function parseBlockedItemIDExpression(value){return parseMarketItemIDExpression(value,'blocked item IDs','屏蔽物品 ID ')}
function parseAllowedItemIDExpression(value){return parseMarketItemIDExpression(value,'allowed item IDs','物品 ID 白名单')}
function formatMarketItemIDs(values){const ids=[...new Set((values||[]).map(Number).filter(x=>Number.isInteger(x)&&x>0&&x<=4294967295))].sort((a,b)=>a-b),ranges=[];for(const id of ids){const last=ranges[ranges.length-1];if(last&&id===last[1]+1)last[1]=id;else ranges.push([id,id])}return ranges.map(x=>x[0]===x[1]?String(x[0]):x[0]+'-'+x[1]).join(',')}
function formatBlockedItemIDs(values){return formatMarketItemIDs(values)}
function formatAllowedItemIDs(values){return formatMarketItemIDs(values)}
function normalizeRarityDigits(value){const seen=new Set();return String(value??'').replace(/[^0-9]/g,'').split('').sort().filter(d=>!seen.has(d)&&seen.add(d)).join('')}function sanitizeMarketAllowedRarities(el){el.value=normalizeRarityDigits(el.value)}function validateMarketRarityScoreCurve(value){const text=String(value??'').trim();if(!text)return;let lastRarity=-1,lastScore=-1;for(const part of text.split(';')){const match=part.trim().match(/^\(\s*(\d+)\s*,\s*(\d+(?:\.\d+)?)%\s*\)$/);if(!match)throw new Error(marketText('Invalid rarity score distribution. Use (rarity,score%); entries.','稀有度权重内部分布格式错误，请使用 (稀有度,百分比%); 格式。'));const rarity=Number(match[1]),score=Number(match[2]);if(rarity<0||rarity>9||!Number.isInteger(rarity))throw new Error(marketText('Rarity score entries must use rarities 0-9.','稀有度权重内部分布只能使用 0-9。'));if(rarity<=lastRarity)throw new Error(marketText('Rarity score entries must be ordered and unique.','稀有度权重内部分布的稀有度必须按顺序且不能重复。'));if(score<0||score>100||score<lastScore)throw new Error(marketText('Rarity scores must be non-decreasing percentages from 0 to 100.','稀有度权重内部分布必须是 0-100 且按稀有度递增。'));lastRarity=rarity;lastScore=score}}
async function submitMarketSettings(){let payload;try{payload=marketFormPayload()}catch(e){toast(e.message);return}if(!payload.equipment_allowed_rarities||!payload.other_allowed_rarities){toast(marketText('Enter at least one rarity for both groups.','装备和其他物品都请至少填写一个稀有度数字。'));return}if(!confirm(marketText('Save settings and start rebuilding Robot auction stock in the background? The current ItemInfo will not be exported or modified.','保存设置并在后台重建机器人拍卖库存？不会导出或修改当前 ItemInfo。')))return;closeModal();await guarded(marketText('Rebuild started','已开始后台重建'),async()=>{const x=await api('marketApplyListingConfig',payload);setTimeout(refreshAll,1000);return x})}
async function submitMarketStart(){closeModal();await guarded('Market start',async()=>api('marketStart',{}))}
async function submitMarketStop(){closeModal();await guarded('Market stop',async()=>api('marketStop',{}))}
async function submitMarketCollect(){closeModal();await guarded('Market recycle',async()=>({auction:await api('marketCollectOnce',{market:'auction',continue_on_error:true}),cera:await api('marketCollectOnce',{market:'cera',continue_on_error:true})}))}
async function submitMarketRestock(){await guarded('Market restock',async()=>({auction:await api('marketRestockOnce',{market:'auction',continue_on_error:true}),cera:await api('marketRestockOnce',{market:'cera',continue_on_error:true})}))}
async function submitMarketClearStock(){closeModal();await guarded('Market clear stock',async()=>api('marketClearSystemStock',{}))}
async function submitMarketItemInfo(){closeModal();await guarded('Market iteminfo',async()=>api('marketSyncItemInfo',{}))}
async function submitMarketAuctionGuard(){closeModal();await guarded('Auction guard',async()=>{const x=await api('marketInstallAuctionGuard',{});const r=resultOf(x)||{};toast(r.changed?i18nFormat('message.guard_installed'):(r.message?i18nText(r.message):i18nFormat('message.guard_exists')));return x})}
async function submitMarketMemoryPatch(){closeModal();await guarded('Auction memory patch',async()=>{const x=await api('marketPatchAuctionMemory',{});const r=resultOf(x)||{};const ok=(r.entries||[]).filter(e=>e.ok).length;toast(i18nFormat('message.memory_patch_result',{ok,total:(r.entries||[]).length||0,pid:r.pid||'-'}));return x})}
async function openPartyCompatDialog(){await guarded('Party',async()=>{const x=await fetch('/api/party-compat').then(r=>r.json());if(!x.ok)throw new Error(x.error||i18nFormat('error.status_failed'));const s=x.result||{};const detail=[i18nText(s.state||'-')];if(s.next_retry_sec)detail.push(i18nFormat('party.retry',{seconds:s.next_retry_sec}));if(s.fail_count)detail.push(i18nFormat('party.failures',{count:s.fail_count}));const msg=s.message?('<div class="muted" style="grid-column:1/-1">'+escapeHTML(i18nText(s.message))+'</div>'):'';const body='<div class="formgrid"><label>Desired</label><div>'+escapeHTML(i18nFormat(s.desired_enabled?'common.on':'common.off'))+'</div><label>Actual</label><div>'+escapeHTML(detail.join(' / '))+'</div><label>Game process</label><div>PID '+escapeHTML(s.pid||'-')+' / '+escapeHTML(i18nFormat('party.port',{port:s.port||'-'}))+'</div><label>Skills</label><label><input id="partySkillEnabled" type="checkbox" '+(s.skill_enabled?'checked':'')+'> Cast</label><label>Account start</label><input class="party-account-input" id="partyCompatStart" type="number" min="1" max="4294967295" value="'+escapeHTML(s.account_start||17000000)+'"><label>Account end</label><input class="party-account-input" id="partyCompatEnd" type="number" min="1" max="4294967295" value="'+escapeHTML(s.account_end||17001000)+'">'+msg+'</div>';showModal('Party',body,'<button onclick="submitPartyCompat(\'off\')">Off</button><button class="primary" onclick="submitPartyCompat(\'on\')">On</button>');return x})}
async function submitPartyCompat(action){const account_start=Math.floor(Number(byId('partyCompatStart').value||0)),account_end=Math.floor(Number(byId('partyCompatEnd').value||0)),skill_enabled=!!byId('partySkillEnabled')?.checked;if(!account_start||account_end<=account_start){toast(i18nFormat('result.failed',{action:i18nFormat('operation.party_patch'),error:i18nFormat('validation.account_range')}));return}closeModal();await guarded(i18nFormat('operation.party_patch')+' '+i18nFormat(action==='on'?'common.on':'common.off'),async()=>{const x=await fetch('/api/party-compat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,account_start,account_end,skill_enabled})}).then(r=>r.json());if(!x.ok)throw new Error(x.error||i18nFormat('error.update_failed'));return x})}
async function openDiagnosticsDialog(){await guarded('Diagnostics',async()=>{const [x,p]=await Promise.all([fetch('/api/diagnostics').then(r=>r.json()),api('partyDebugStatus')]);showDiagnosticsDialog(x,resultOf(p)||{});return x})}
function statusPill(s,translate=true){s=String(s||'ok');const cls=s==='error'?'error':(s==='warn'?'warn':'ok');const label=translate?(s==='error'?i18nFormat('common.error'):(s==='warn'?i18nFormat('common.warn'):i18nFormat('common.ok'))):(s==='error'?'Error':(s==='warn'?'Warn':'OK'));return '<span class="pill '+cls+'">'+escapeHTML(label)+'</span>'}
function partyDebugActionsHTML(p){const state=String(p.state||'idle'),active=state==='capturing'||state==='analyzing',elapsed=Math.max(0,Number(p.elapsed_ms||0)),used=Math.max(0,Number(p.bytes_used||0));const status=state==='capturing'?('Capturing '+(elapsed/1000).toFixed(1)+'s · '+formatDebugBytes(used)):(state==='analyzing'?'Analyzing':'');return '<span class="diag-debug-state">'+escapeHTML(status)+'</span><button id="partyDebugStart" class="diagtextbtn" onclick="startPartyDebug()" '+(active?'disabled':'')+'>Start Party Debug</button><button id="partyDebugStop" class="diagtextbtn" onclick="stopPartyDebug()" '+(state==='capturing'?'':'disabled')+'>Stop &amp; Analyze</button>'}
function formatDebugBytes(value){if(value>=1048576)return (value/1048576).toFixed(2)+'MB';if(value>=1024)return (value/1024).toFixed(1)+'KB';return value+'B'}
function showDiagnosticsDialog(r,p){const sum=r.summary||{};let body='<div class="formgrid"><label>Generated</label><div>'+escapeHTML(r.generated_at||'-')+'</div><label>Summary</label><div>OK '+escapeHTML(sum.ok||0)+' / Warn '+escapeHTML(sum.warnings||0)+' / Error '+escapeHTML(sum.errors||0)+'</div></div>';for(const sec of (r.sections||[])){const actions=sec.name==='Party'?('<span id="partyDebugActions" class="diagpartyactions">'+partyDebugActionsHTML(p)+'</span>'):'';body+='<div class="diagsec"><div class="diaghead"><span>'+escapeHTML(sec.name||'-')+'</span>'+actions+'</div>';for(const c of (sec.checks||[])){body+='<div class="diagrow"><div>'+escapeHTML(c.name||'-')+'</div><div>'+statusPill(c.status,false)+'</div><div>'+escapeHTML(c.message||'')+'</div></div>'}body+='</div>'}showModal('Diagnostics',body,'<button onclick="closeModal()">Close</button>','diagnostics',false);setTimeout(()=>updatePartyDebugControls(p),0);schedulePartyDebugPoll(p)}
function updatePartyDebugControls(p){const el=byId('partyDebugActions');if(!el)return;el.innerHTML=partyDebugActionsHTML(p)}
function schedulePartyDebugPoll(p){if(partyDebugTimer){clearTimeout(partyDebugTimer);partyDebugTimer=null}const state=String(p.state||'');if(state!=='capturing'&&state!=='analyzing')return;partyDebugTimer=setTimeout(async()=>{try{const x=await api('partyDebugStatus'),next=resultOf(x)||{};if((next.state||'')==='ready'){showPartyDebugResult(next)}else{updatePartyDebugControls(next);schedulePartyDebugPoll(next)}}catch(e){const s=document.querySelector('.diag-debug-state');if(s)s.textContent='Status error: '+e.message}},1000)}
async function startPartyDebug(){const a=byId('partyDebugStart'),b=byId('partyDebugStop');if(a)a.disabled=true;if(b)b.disabled=true;try{const x=await api('partyDebugStart'),p=resultOf(x)||{};updatePartyDebugControls(p);schedulePartyDebugPoll(p)}catch(e){if(a)a.disabled=false;const s=document.querySelector('.diag-debug-state');if(s)s.textContent='Start failed: '+e.message}}
async function stopPartyDebug(){const b=byId('partyDebugStop');if(b)b.disabled=true;try{const x=await api('partyDebugStop');showPartyDebugResult(resultOf(x)||{})}catch(e){if(b)b.disabled=false;const s=document.querySelector('.diag-debug-state');if(s)s.textContent='Stop failed: '+e.message}}
function showPartyDebugResult(p){if(partyDebugTimer){clearTimeout(partyDebugTimer);partyDebugTimer=null}const report=(p.report_lines||[]).join('\n')||'No Party debug data was captured.';const body='<pre class="party-debug-result">'+escapeHTML(report)+'</pre>';showModal('Party Debug Result',body,'<button onclick="closeModal()">Close</button>','diagnostics',false)}
async function releaseDefaultKeypair(){closeModal();await guarded('Release Bundled Default Key',async()=>api('keypairReleaseDefault',{}))}
function downloadDefaultKeypair(){window.location='/api/keypair-download'}
function toggleAutoRefresh(){if(autoRefreshTimer){clearInterval(autoRefreshTimer);autoRefreshTimer=null}const el=byId('autoRefreshInterval');const v=el?.value;if(v)localStorage.setItem('tw_auto_refresh_interval',v);if(v&&v!=='off')autoRefreshTimer=setInterval(refreshQuiet,Number(v))}
function restoreAutoRefresh(){const saved=localStorage.getItem('tw_auto_refresh_interval');const el=byId('autoRefreshInterval');if(saved&&el&&[...el.options].some(o=>o.value===saved))el.value=saved;toggleAutoRefresh()}
let backendCapabilities={},selectedBackendID='';
function ensureBackendControl(){if(byId('backendButton'))return;const logout=document.querySelector('header a[href="/logout"]');if(!logout||!logout.parentElement)return;const button=document.createElement('button');button.id='backendButton';button.className='headlink';button.dataset.i18n='backend.title';button.textContent=i18nFormat('backend.title');button.onclick=openBackendDialog;logout.parentElement.insertBefore(button,logout)}
async function openBackendDialog(){try{const r=await fetch('/api/backend').then(x=>x.json());if(!r.ok)throw new Error(r.error||i18nFormat('backend.query_failed'));const rows=(r.backends||[]).map(b=>'<option value="'+escapeHTML(b.id)+'" '+(b.id===r.selected?'selected':'')+' '+(b.selectable?'':'disabled')+'>'+escapeHTML(b.display_name||b.id)+'</option>').join('');const body='<div class="formgrid"><label>'+i18nFormat('backend.selected')+'</label><select id="backendChoice">'+rows+'</select><div class="muted" style="grid-column:1/-1">'+i18nFormat('backend.restart_hint')+'</div></div>';showModal(i18nFormat('backend.title'),body,'<button onclick="closeModal()">'+i18nFormat('common.cancel')+'</button><button class="primary" onclick="submitBackendSelection()">'+i18nFormat('backend.select')+'</button>','compact',false)}catch(e){toast(i18nFormat('backend.title')+': '+e.message)}}
async function submitBackendSelection(){const id=byId('backendChoice')?.value;if(!id)return;closeModal();await guarded('Backend',async()=>{const r=await fetch('/api/backend',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({backend_id:id})}).then(x=>x.json());if(!r.ok)throw new Error(r.error||'backend selection failed');selectedBackendID=r.selected||'';backendCapabilities=((r.backends||[]).find(b=>b.id===selectedBackendID)||{}).capabilities||{};applyBackendCapabilities();showModal('Backend selected','<p>'+escapeHTML(r.message||'Backend selected.')+'</p><p>Restart required: '+(r.restart_required?'yes':'no')+'<br>Reinitialize required: '+(r.reinitialize_needed?'yes':'no')+'</p>','<button onclick="closeModal()">Close</button>','compact',false);return r})}
function applyBackendCapabilities(){document.querySelectorAll('button[onclick]').forEach(b=>{const cmd=b.getAttribute('onclick')||'';let cap='';if(cmd.includes("openKeyDialog")||cmd.includes("downloadDefaultKeypair")||cmd.includes("releaseDefaultKeypair"))cap='keypair';else if(cmd.includes("robotsMove"))cap='town_move';else if(cmd.includes("robotsShout"))cap=backendCapabilities.world_shout?.enabled?'world_shout':'shout';else if(cmd.includes("robotsStore"))cap='store';else if(cmd.includes("openPartyCompat"))cap='party';else if(cmd.includes("openCompatDialog"))cap='compatibility';else if(cmd.includes("openDiagnosticsDialog"))cap='diagnostics';else if(cmd.includes("openCleanupDialog"))cap='cleanup';else if(cmd.includes("openMarket"))cap='market';else if(cmd.includes("openMaxDialog")||cmd.includes("openScriptDialog"))cap='market';if(!cap)return;const status=backendCapabilities[cap]||{};const disabled=busy||!status.enabled;b.disabled=disabled;b.title=!status.enabled?(status.reason||'backend capability unavailable'):''})}
async function refreshBackendCapabilities(){try{const r=await fetch('/api/backend').then(x=>x.json());selectedBackendID=r.selected||'';const selected=(r.backends||[]).find(b=>b.id===selectedBackendID);backendCapabilities=selected?.capabilities||{};applyBackendCapabilities()}catch(e){}}
async function bootWeb(){ensureBackendControl();i18nApply(document);await refreshBackendCapabilities();await refreshAll();restoreAutoRefresh()}bootWeb();
